module multi_8bit(
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

reg [15:0] partial_product;
reg [3:0] counter;

always @(*) begin
    partial_product = 16'b0;
    counter = 4'b0;

    while (counter < 8) begin
        if (B[counter]) begin
            partial_product = partial_product + (A << counter);
        end
        counter = counter + 1;
    end

    product = partial_product;
end

endmodule
